public static function unreadBadgeCount(int $userId, string $role, array $campusIds): int
{
    $reporter = self::countReporterReplyUnread($userId, $campusIds);
    if ($role === 'super_admin') {
        return $reporter + self::countNewBugsForSuperAdminInbox($userId, $campusIds);
    }
    if ($role === 'director' || $role === 'admin') {
        return $reporter + self::countNewBugsFromOthersInCampuses($userId, $campusIds);
    }

    return $reporter;
}

/**
 * Director / admin: new submissions from other users in the scoped campus(es).
 * Clears naturally when super_admin (or status workflow) moves bugs out of `new`.
 */
private static function countNewBugsFromOthersInCampuses(int $userId, array $campusIds): int
{
    if (empty($campusIds)) {
        return 0;
    }

    return (int) BugReport::query()
        ->where('status', 'new')
        ->whereIn('CampusID', $campusIds)
        ->where('reporter_user_id', '!=', $userId)
        ->count();
}

