    $student = $this->createStudent(1, '批次排課錨點測試');

    $pastDate = now()->subDays(2)->toDateString();
    $futureDate = now()->addDays(5)->toDateString();

    $res = $this->withHeaders([
        'Authorization' => "Bearer {$token}",
        'Accept' => 'application/json',
    ])->postJson('/api/v1/class-sessions/batch', [
        'branch_id' => 1,
        'student_id' => $student->id,
        'teacher_id' => $teacherId,
        'subject' => 'Math',
        'class_type' => 'one_on_one',
        'total_classes' => 2,
        'confirmed_dates' => [],
        'future_dates' => [$pastDate, $futureDate],
        'days_of_week' => [1, 4],
        'start_time' => '16:00',
        'duration_minutes' => 120,
        'price_per_session' => 500,
        'payment_type' => 'session',
        'mode' => 'create',
    ]);

    $res->assertCreated()
        ->assertJsonPath('created_sessions', 2)
        ->assertJsonPath('deducted_sessions', 0)
        ->assertJsonPath('created_learning_records', 0);

    $studentClassId = (int) ($res->json('student_class_id') ?? 0);
    $this->assertDatabaseHas('StudentClass', [
        'ID' => $studentClassId,
        'SessionCount' => 2,
        'RemainingSessions' => 2,
        'UsedSessions' => 0,
    ]);

    $sessions = DB::table('ClassSession')
        ->where('StudentClassID', $studentClassId)
        ->orderBy('SessionDate')
        ->get();
    $this->assertCount(2, $sessions);
    $this->assertSame('scheduled', (string) ($sessions[0]->Status ?? ''));
    $this->assertSame('scheduled', (string) ($sessions[1]->Status ?? ''));
}

